INSERT IGNORE INTO san_pham
(id, ma_san_pham, ten_san_pham, gia_ban, gia_khuyen_mai, so_luong_ton, hinh_anh, anh_phu, cong_suat, bao_hanh_thang, mo_ta, thong_so_ky_thuat, dang_ban, loai_san_pham_id, thuong_hieu_id) VALUES
(1, 'BDT-BOS-001', 'Bếp từ Bosch PID675DC1E', 20610000, 15240000, 6, '/img/sp/bdt-bos-001/1.jpg', '/img/sp/bdt-bos-001/2.jpg', '7400W', 36, 'Bếp từ ba vùng nấu Bosch PID675DC1E là mẫu bếp lắp âm thuộc thương hiệu Bosch của Đức, sản xuất tại Tây Ban Nha, dành cho những gian bếp đề cao hiệu năng và độ chính xác khi nấu. Với tổng công suất 7400W chia cho ba vùng nấu, bếp cho phép chế biến nhiều món cùng lúc mà không phải chờ đợi giữa các lần nấu.\nThiết kế của PID675DC1E theo phong cách châu Âu tối giản với mặt kính đen sang trọng, vát cạnh tinh tế và bo viền thép không gỉ, dễ hoà hợp với nhiều phong cách nội thất. Mặt bếp làm từ kính Ceramic Schott Ceran của Đức, chịu lực và chịu nhiệt tốt, bề mặt bóng sáng nên việc vệ sinh sau khi nấu rất nhẹ nhàng.\nKích thước sản phẩm 51 x 606 x 527 mm với kích thước lắp đặt 51 x 560 x 490-500 mm. Ba vùng nấu được bố trí hợp lý: vùng bên trái linh hoạt với các đường kính 21, 26 và 32 cm cho công suất 2200/2600/3300W, vùng phải trên đường kính 14,5 cm và vùng phải dưới đường kính 21 cm, phù hợp với đủ loại nồi chảo trong bếp Việt.', 'Thương hiệu: Bosch (Đức); Model: PID675DC1E; Sản xuất tại: Tây Ban Nha; Kiểu lắp: Âm tủ; Chất liệu: Kính; Điện áp: 220-240V; Tổng công suất (W): 7400; Kiểu điều khiển: Cảm ứng; Số vùng nấu: 3; KT mặt kính (R×S mm): 606 x 527; KT khoét đá (R×S mm): 560 x 490; Công suất từng vùng (W): 3300 + 2200 + 1400; Booster: Có; CS Booster tối đa (W): 3700; Mặt kính: Schott Ceran (Đức); Công nghệ bo mạch: Inverter; An toàn: Khoá trẻ em, tự ngắt, cảnh báo nhiệt dư 2 mức, khoá chống lau, công tắc chính', 1, 1, 1),
(2, 'BDT-KAF-001', 'Bếp từ Kaff KF-IH202IC', 28800000, 20810000, 14, '/img/sp/bdt-kaf-001/1.jpg', '/img/sp/bdt-kaf-001/2.jpg|/img/sp/bdt-kaf-001/3.jpg', '4500W', 36, 'Bếp điện từ Kaff KF-IH202IC là một sản phẩm cao cấp đến từ thương hiệu Kaff của Đức, được sản xuất trên dây chuyền công nghệ hiện đại theo tiêu chuẩn Châu Âu. Sản phẩm này sở hữu thiết kế 2 lò nấu từ cùng với công nghệ Booster tiên tiến, giúp rút ngắn thời gian nấu nướng và tiết kiệm thời gian cho người dùng.\nCác tính năng an toàn và ưu việt của bếp điện từ Kaff KF-IH202IC bao gồm khóa trẻ em, tự động tắt bếp khi để quên và khi không có nồi, chức năng hẹn giờ, và cảm ứng chống tràn, cảm ứng quá nhiệt. Bếp điện từ Kaff KF-IH202IC có thiết kế mặt kính làm bằng kính Schott Ceran sang trọng, chống trơn trượt và có khả năng chịu nhiệt lên đến 1000 độ C, chịu sốc nhiệt tốt.\nMặt kính này là mặt kính chuyên dụng dành cho bếp điện, với chất lượng cao, rất cứng, bền và có khả năng truyền nhiệt và tản nhiệt nhanh.', 'Thương hiệu: Kaff (Đức); Model: KF-IH202IC; Sản xuất tại: Đức; Kiểu lắp: Âm tủ; Chất liệu: Kính; Điện áp: 220-240V; Tổng công suất (W): 4500; Kiểu điều khiển: Cảm ứng trượt (Slider); Số vùng nấu: 2; KT mặt kính (R×S mm): 730 x 430; KT khoét đá (R×S mm): 690 x 380; Công suất từng vùng (W): 2300 + 2200; Booster: Có; CS Booster tối đa (W): 3200; Mặt kính: Schott Ceran (Đức); Công nghệ bo mạch: Inverter; An toàn: Tự ngắt, nhận diện nồi, khóa trẻ em, chống tràn, chống quá nhiệt', 1, 1, 2),
(3, 'BDT-KOC-001', 'Bếp từ Kocher X-NANO 6 Plus', 19400000, 12380000, 7, '/img/sp/bdt-koc-001/1.jpg', NULL, '4000W', 36, 'Bếp từ Kocher X-NANO 6 Plus là mẫu bếp từ đôi lắp âm nổi bật với mặt kính X-Nano thế hệ mới, giải quyết trực tiếp nỗi lo lớn nhất của người dùng bếp từ là mặt kính bị xước dăm sau thời gian sử dụng. Sản phẩm hướng tới những gia đình muốn một chiếc bếp vừa mạnh, vừa giữ được vẻ đẹp lâu dài mà không phải nâng niu quá mức khi nấu hằng ngày.\nMặt kính tinh thể X-Nano được sản xuất theo công nghệ độc quyền từ Pháp, có khả năng kháng lại các vết xước dăm do đáy nồi chảo tốt gấp 5 lần so với kính bóng thông thường. Nhờ đặc tính bề mặt mờ, dầu mỡ và chất bẩn khó bám chặt nên việc vệ sinh nhanh hơn hẳn, đồng thời lớp hoàn thiện Black Matte sang trọng gần như không lưu lại dấu vân tay khi thao tác.\nCấu trúc vân nhám siêu vi còn tạo độ bám cơ học lý tưởng, giúp cố định nồi chảo tại tâm nhiệt và loại bỏ hiện tượng trơn trượt khi có nước hoặc dầu tràn ra mặt bếp.', 'Thương hiệu: Kocher (Đức); Model: X-NANO 6 Plus; Sản xuất tại: Thái Lan; Kiểu lắp: Âm tủ; Chất liệu: Kính / Nhôm; Điện áp: 220-240V / 50-60Hz; Tổng công suất (W): 4000; Kiểu điều khiển: Cảm ứng trượt (Slider); Số vùng nấu: 2; KT mặt kính (R×S mm): 730 x 420; KT khoét đá (R×S mm): 695 x 395; Công suất từng vùng (W): 2000 + 2000; Booster: Có; CS Booster tối đa (W): 2300; Mặt kính: EuroKera (Pháp); Công nghệ bo mạch: Inverter; An toàn: Khoá trẻ em, cảnh báo chống tràn, tự ngắt khi không nồi, hẹn giờ', 1, 1, 3),
(4, 'BDT-CHE-001', 'Bếp từ Chef''s EH-DIH666', 15500000, 11340000, 16, '/img/sp/bdt-che-001/1.jpg', NULL, '4400W', 36, 'Bếp có hai vùng nấu, kích thước 720 x 430 x 60 mm và kích thước khoét đá 700 x 380 x 30 mm, dùng nguồn điện 220V thông dụng. Mặt bếp sử dụng kính Schott Ceran vát cạnh, bo viền hai cạnh bên nhằm hạn chế nứt vỡ do va chạm và tăng thẩm mỹ cho khu vực nấu.\nChất kính chịu nhiệt, chịu lực tốt, bề mặt bóng sáng nên việc lau chùi sau mỗi bữa ăn rất nhanh gọn. EH-DIH666 thuộc dòng bếp từ Inverter nên kiểm soát công suất mượt mà và tiết kiệm điện hơn so với bếp điều khiển đóng ngắt truyền thống.\nMỗi vùng nấu đạt công suất 2200W và có thể tăng lên 3000W khi kích hoạt Booster, đủ sức đun sôi nhanh, xào nấu ở lửa lớn. Tính năng chia sẻ công suất tự động giúp bếp phân bổ điện năng hợp lý khi bật đồng thời hai vùng.\nBảng điều khiển cảm ứng trượt Touch Control độ nhạy cao với 9 mức công suất, kèm màn hình hiển thị rõ ràng, dễ dùng cho cả người lớn tuổi.', 'Thương hiệu: Chef''s (Việt Nam); Model: EH-DIH666; Sản xuất tại: Việt Nam; Kiểu lắp: Âm tủ; Chất liệu: Kính; Điện áp: 220V / 50Hz; Tổng công suất (W): 4400; Kiểu điều khiển: Cảm ứng; Số vùng nấu: 2; KT mặt kính (R×S mm): 730 x 430; KT khoét đá (R×S mm): 670 x 370; Công suất từng vùng (W): 2200 + 2200; Booster: Có; CS Booster tối đa (W): 3000; Mặt kính: Schott Ceran (Đức); Công nghệ bo mạch: Inverter; An toàn: Khoá trẻ em/bàn phím, cảnh báo nhiệt dư, tự ngắt khi quá nhiệt/quá tải, nhận diện nồi, tự tắt khi để quên', 1, 1, 4),
(5, 'BHN-KAF-001', 'Bếp đôi từ hồng ngoại Kaff KF-IC5801SB', 25580000, 20210000, 11, '/img/sp/bhn-kaf-001/1.jpg', NULL, '6000W', 36, 'Bếp điện từ Kaff KF-IC5801SB là mẫu bếp ba vùng nấu kết hợp hai vùng từ và một vùng hồng ngoại, nhập khẩu nguyên chiếc từ CHLB Đức. Với ba vùng nấu hoạt động độc lập, bếp giúp rút ngắn đáng kể thời gian chuẩn bị bữa ăn cho gia đình đông thành viên, đồng thời vẫn giữ được sự linh hoạt nhờ vùng hồng ngoại không kén nồi.\nMặt bếp sử dụng kính Schott Ceran sản xuất tại Đức, chất liệu gốm thủy tinh chịu nhiệt tới 1000°C và kháng sốc nhiệt 750°C. Bề mặt chịu được thay đổi nhiệt độ đột ngột, độ giãn nở vì nhiệt thấp nên bếp vận hành hiệu quả và cách nhiệt tốt.\nMặt kính liền khối, chống trầy xước, tản nhiệt nhanh và được cách điện an toàn với linh kiện điện tử bên trong thân bếp. Kích thước mặt kính 780x450 mm cùng kích thước khoét đá 750x380 mm phù hợp với mặt đá tủ bếp rộng rãi.\nBa vùng nấu có công suất lần lượt 1800W, 1500W và 2200W, hoạt động ở điện áp 220-240V/50-60Hz.', 'Thương hiệu: Kaff (Đức); Model: KF-IC5801SB; Sản xuất tại: Đức; Kiểu lắp: Âm tủ; Chất liệu: Kính; Điện áp: 220-240V; Tổng công suất (W): 6000; Kiểu điều khiển: Cảm ứng trượt (Slider); Số vùng nấu: 3; KT mặt kính (R×S mm): 780 x 450; KT khoét đá (R×S mm): 750 x 380; Công suất từng vùng (W): 2300 + 1500 + 2200; Booster: Có; CS Booster tối đa (W): 3700; Mặt kính: Schott Ceran (Đức); Công nghệ bo mạch: Inverter; An toàn: Có', 1, 2, 2),
(6, 'BHN-KAF-002', 'Bếp đôi từ hồng ngoại Kaff KF-IH68N', 22800000, 18020000, 9, '/img/sp/bhn-kaf-002/1.jpg', '/img/sp/bhn-kaf-002/2.jpg|/img/sp/bhn-kaf-002/3.jpg', '4500W', 36, 'Bếp điện từ Kaff KF-IH68N là mẫu bếp hai vùng nấu kết hợp một bên từ và một bên hồng ngoại, xuất xứ Germany. Thiết kế này mang lại sự linh hoạt hiếm có: vùng từ đun nấu nhanh, tập trung nhiệt và tiết kiệm điện khi dùng nồi inox nhiễm từ, còn vùng hồng ngoại không kén nồi, phù hợp cho những món cần lửa nhỏ, giữ ấm hay nướng trực tiếp trên mặt kính.\nMặt bếp sử dụng kính gốm thủy tinh Schott Ceran sản xuất tại Đức, nổi bật với khả năng chịu nhiệt và chống sốc nhiệt, chống trầy xước, chịu va đập tốt. Độ giãn nở vì nhiệt thấp nên bếp giữ nhiệt hiệu quả, đồng thời tản nhiệt nhanh và cách điện an toàn với linh kiện điện tử bên trong thân máy.\nMặt kính màu xám liền nguyên khối vừa tăng tính thẩm mỹ cho không gian bếp, vừa rất tiện khi lau chùi. Kích thước sản phẩm 730x430 mm, khoét đá 680x380 mm, trọng lượng khoảng 14 kg.\nVề công nghệ, KF-IH68N dùng bo mạch IGBT Siemens của Đức cùng công nghệ biến tần Inverter giúp tiết kiệm tới 40% điện năng.', 'Thương hiệu: Kaff (Đức); Model: KF-IH68N; Sản xuất tại: Đức; Kiểu lắp: Âm tủ; Chất liệu: Kính; Tổng công suất (W): 4500; Kiểu điều khiển: Cảm ứng trượt (Slider); Số vùng nấu: 2; KT mặt kính (R×S mm): 680 x 380; Công suất từng vùng (W): 2300 + 2200; Booster: Có; CS Booster tối đa (W): 4000; Mặt kính: Schott Ceran (Đức); An toàn: Child lock, Auto shutoff, Cookware detection', 1, 2, 2),
(7, 'BHN-KOC-001', 'Bếp đôi từ hồng ngoại Kocher EI-355', 21500000, 11640000, 13, '/img/sp/bhn-koc-001/1.jpg', '/img/sp/bhn-koc-001/2.jpg|/img/sp/bhn-koc-001/3.jpg', '5100W', 36, 'Bếp từ Kocher EI-355 là một thiết bị nấu ăn hiện đại và thông minh, đáp ứng mọi nhu cầu của người nội trợ. Với thiết kế và 3 vùng nấu linh hoạt, bao gồm 2 vùng từ và 1 vùng hồng ngoại, bếp từ Kocher EI-355 mang đến khả năng chế biến đa dạng và tiện lợi.\nMặt kính Keramik cao cấp với khả năng chịu lực và chịu nhiệt vượt trội, hạn chế tối đa trầy xước trong quá trình nấu nướng. Bếp từ Kocher EI-355 được trang bị công nghệ Inverter tiên tiến, giúp duy trì nhiệt độ ổn định, giảm thất thoát nhiệt và tối ưu điện năng tiêu thụ.\nĐiều khiển cảm ứng Slider thông minh với 9 mức công suất cho phép tăng giảm nhiệt độ mượt mà chỉ bằng một thao tác chạm. Hệ thống an toàn toàn diện với các tính năng như tự động ngắt khi quá nhiệt, chống tràn thông minh, khóa an toàn trẻ em và chế độ hẹn giờ cho từng vùng nấu, giúp quá trình nấu nướng luôn an toàn.', 'Thương hiệu: Kocher (Đức); Model: EI-355; Sản xuất tại: Hàn Quốc; Kiểu lắp: Âm tủ; Chất liệu: Kính; Điện áp: 220-240V / 50-60Hz; Tổng công suất (W): 5100; Kiểu điều khiển: Cảm ứng trượt (Slider); Số vùng nấu: 3; KT mặt kính (R×S mm): 780 x 450; KT khoét đá (R×S mm): 680 x 380; Công suất từng vùng (W): 1800 + 1500 + 2300; Booster: Có; CS Booster tối đa (W): 3000; Mặt kính: Kính ceramic; Công nghệ bo mạch: Inverter; An toàn: Khoá trẻ em, chống tràn, báo nhiệt dư, tự tắt quá nhiệt, hẹn giờ 1-99 phút/vùng', 1, 2, 3),
(8, 'BHN-CHE-001', 'Bếp đôi từ hồng ngoại Chef''s EH-MIX333', 13900000, 10170000, 25, '/img/sp/bhn-che-001/1.jpg', NULL, '5200W', 36, 'Bếp điện từ Chef''s EH-MIX333 là mẫu bếp hỗn hợp lắp âm gồm một vùng nấu từ và một vùng nấu điện hồng ngoại, giải pháp phù hợp cho những gia đình vẫn đang dùng song song nhiều loại nồi chảo khác nhau. Vùng nấu từ cho tốc độ làm nóng nhanh và hiệu suất cao, trong khi vùng nấu điện sử dụng được với hầu hết các loại nồi, kể cả nồi đất, nồi thủy tinh hay nồi nhôm không nhiễm từ.\nKích thước sản phẩm 720x420x60 mm với kích thước khoét đá 670x380 mm, phù hợp với đa số mặt đá bàn bếp thông dụng. Bên trong bếp sử dụng mâm nhiệt E.G.O, linh kiện quen thuộc trên các dòng bếp điện từ cao cấp, cho khả năng làm nóng nhanh và phân bố nhiệt đều.\nVề công suất, vùng nấu điện có hai vòng nhiệt Ø14/22 cm với công suất tối đa 2000W, cho phép chọn vòng nhỏ khi dùng nồi đáy nhỏ và vòng lớn khi dùng nồi đáy rộng, tránh thất thoát nhiệt. Vùng nấu từ đường kính 22 cm đạt công suất tối đa 3000W, đủ mạnh cho các món cần lửa lớn như xào, áp chảo hay đun sôi nhanh.', 'Thương hiệu: Chef''s (Việt Nam); Model: EH-MIX333; Sản xuất tại: Việt Nam; Kiểu lắp: Âm tủ; Chất liệu: Kính; Điện áp: 220V / 50Hz; Tổng công suất (W): 5200; Kiểu điều khiển: Cảm ứng trượt (Slider); Số vùng nấu: 2; KT mặt kính (R×S mm): 720 x 420; KT khoét đá (R×S mm): 670 x 380; Công suất từng vùng (W): 2200 + 3000; Booster: Có; CS Booster tối đa (W): 3000; Mặt kính: Schott Ceran (Đức); Thương hiệu mâm từ: E.G.O (Đức); An toàn: Khóa trẻ em, cảnh báo nhiệt dư, tự động tắt khi nhấc nồi, bảo vệ quá nhiệt/quá dòng', 1, 2, 4),
(9, 'HM-BOS-001', 'Máy hút mùi Bosch DWB97BK61T', 12990000, 10370000, 4, '/img/sp/hm-bos-001/1.jpg', NULL, '582 m3/h', 36, 'Máy hút mùi Bosch DWB97BK61T thuộc dòng Serie 4, là mẫu hút mùi gắn tường khổ 90 cm dành cho những căn bếp rộng rãi hoặc không gian bếp mở liền phòng khách. Sản phẩm mang thương hiệu Bosch của Đức, được sản xuất tại Thổ Nhĩ Kỳ, hướng tới người dùng cần lực hút lớn cùng độ hoàn thiện cao.\nMáy có kiểu dáng chữ T hiện đại, thân làm từ thép không gỉ tông màu xám, dễ lau chùi và giữ được vẻ sáng bóng theo thời gian. Kích thước sản phẩm 550-830 x 898 x 500 mm với trọng lượng 21,8 kg, phần ống khói có thể điều chỉnh chiều cao để phù hợp với nhiều trần bếp khác nhau.\nChiều ngang 90 cm rất hợp khi lắp phía trên bếp từ hoặc bếp điện có từ 2 vùng nấu trở lên. Về vận hành, máy được trang bị động cơ EcoSilence Drive nổi tiếng của Bosch, cho khả năng chạy êm và tiết kiệm điện.', 'Thương hiệu: Bosch (Đức); Model: DWB97BK61T; Sản xuất tại: Thổ Nhĩ Kỳ; Kiểu lắp: Áp tường; Chất liệu: Inox / Thép sơn tĩnh điện; Điện áp: 220-240V; Tổng công suất (W): 275; Kiểu điều khiển: Cảm ứng; Kiểu máy: Ống khói; Lưu lượng hút (m³/h): 582; Độ ồn (dB): 66; Số cấp tốc độ: 3; Số motor: 1; Công suất motor (W): 275; Loại lọc: Lọc mỡ; Đèn chiếu sáng: LED; Bề rộng (mm): 898', 1, 3, 1),
(10, 'HM-KAF-001', 'Máy hút mùi Kaff KF-GB773', 7480000, 4930000, 15, '/img/sp/hm-kaf-001/1.jpg', NULL, '1000 m3/h', 36, 'Máy hút mùi Kaff KF-GB773 là mẫu hút mùi kính cong gắn tường khổ 70cm với thân inox sáng, thuộc nhóm sản phẩm bán chạy nhờ thiết kế cân đối, dễ lắp và chi phí vận hành thấp. Kiểu dáng toa inox kết hợp mặt kính cường lực tạo cảm giác chắc chắn, hiện đại mà không kén phong cách tủ bếp.\nThân máy được làm từ inox không gỉ, mặt trước là kính cường lực dày 8mm tráng men bóng cao cấp, bền với nhiệt độ và độ ẩm trong bếp, đồng thời dễ lau chùi. Kích thước sản phẩm 700 x 475 mm phù hợp lắp trên mặt bếp khổ 70cm phổ biến.\nBộ lọc gồm lưới lọc nhôm 5 lớp kết hợp than hoạt tính, tháo rời vệ sinh dễ dàng. Việc rửa lưới lọc định kỳ là yếu tố quan trọng giúp máy giữ được lực hút và tránh dầu mỡ đóng cặn trong buồng động cơ.\nMáy sử dụng động cơ turbin đôi công suất 170W, cho công suất hút tối đa 1000 m3/h, xử lý nhanh khói và mùi từ các món chiên xào nhiều dầu mỡ.', 'Thương hiệu: Kaff (Đức); Model: KF-GB773; Sản xuất tại: Trung Quốc; Kiểu lắp: Áp tường; Chất liệu: Inox / Kính cường lực; Điện áp: 220-240V / 50-60Hz; Tổng công suất (W): 170; Kiểu điều khiển: Cảm ứng; Kiểu máy: Kính cong; KT máy (R×S×C mm): 700 x 475; Lưu lượng hút (m³/h): 1000; Độ ồn (dB): 48; Số cấp tốc độ: 3; Số motor: 1; Công suất motor (W): 170; Loại lọc: Lọc mỡ / Lọc than hoạt tính (khử mùi); Đèn chiếu sáng: LED; Bề rộng (mm): 700; Chất liệu lưới lọc: Nhôm; An toàn: Kính cường lực cong', 1, 3, 2),
(11, 'HM-KAF-002', 'Máy hút mùi Kaff KF-GB705', 6480000, 4270000, 8, '/img/sp/hm-kaf-002/1.jpg', NULL, '1000 m3/h', 36, 'Máy hút mùi Kaff KF-GB705 là mẫu hút mùi kính cong gắn tường khổ 70cm điều khiển bằng phím bấm, dành cho những gia đình ưa sự đơn giản, chắc chắn trong thao tác hằng ngày. Kiểu dáng kính cong kết hợp thân inox sáng đẹp giúp máy dễ hòa hợp với hầu hết mẫu tủ bếp đang phổ biến.\nThân máy bằng inox sáng đẹp, mặt trước là kính cường lực dày 8mm tráng men bóng cao cấp, chịu nhiệt và chịu lực tốt, bề mặt dễ lau sau khi nấu. Kích thước sản phẩm 475 x 700 mm cùng ốp ống khói inox đi kèm giúp phần lắp đặt gọn gàng, cân đối với mặt bếp khổ 70cm.\nBộ lọc gồm lưới lọc nhôm 5 lớp kết hợp than hoạt tính, tháo rời để rửa định kỳ, đây là thao tác đơn giản nhưng quyết định nhiều tới việc máy có giữ được lực hút sau vài năm sử dụng hay không. Máy sử dụng động cơ turbin đôi công suất 170W, cho công suất hút tối đa 1000 m3/h, xử lý nhanh khói và mùi từ các món chiên rán nhiều dầu mỡ.', 'Thương hiệu: Kaff (Đức); Model: KF-GB705; Sản xuất tại: Malaysia; Kiểu lắp: Áp tường; Chất liệu: Inox / Kính cường lực; Điện áp: 220-240V / 50-60Hz; Tổng công suất (W): 170; Kiểu điều khiển: Cơ (công tắc/nút gạt) / Phím bấm; Kiểu máy: Kính cong; KT máy (R×S×C mm): 700 x 475; Lưu lượng hút (m³/h): 1000; Độ ồn (dB): 48; Số cấp tốc độ: 3; Số motor: 1; Công suất motor (W): 170; Loại lọc: Lọc mỡ; Đèn chiếu sáng: LED; Bề rộng (mm): 700; Chất liệu lưới lọc: Nhôm; An toàn: chịu nhiệt, chịu lực cao', 1, 3, 2),
(12, 'HM-KOC-001', 'Máy hút mùi Kocher K-8872V đen-90cm', 8700000, 3780000, 19, '/img/sp/hm-koc-001/1.jpg', '/img/sp/hm-koc-001/2.jpg', '1550 m3/h', 36, 'Máy hút mùi Kocher K-8872V bản màu đen, kích thước 90cm là mẫu hút mùi áp tường kính cong dành cho những căn bếp rộng mang phong cách hiện đại. Sản phẩm đảm nhiệm việc loại bỏ khói, mùi thức ăn và hơi dầu mỡ trong suốt quá trình nấu nướng, giúp căn bếp luôn thông thoáng và hạn chế mùi ám vào nội thất, rèm cửa hay quần áo.\nMáy có thiết kế gắn tường với mặt kính cong dày 6.0mm kết hợp thân máy bằng hợp kim phủ sơn tĩnh điện màu đen nhám, tạo tổng thể sang trọng, dễ phối cùng các mẫu tủ bếp và thiết bị bếp tông tối đang được ưa chuộng. Kích thước tổng thể R900 x S470 x C500 (mm), phù hợp với mặt bếp khổ lớn.\nHệ thống lưới lọc nan inox có độ bền cao, giữ lại dầu mỡ hiệu quả đồng thời góp phần giảm tiếng ồn khi vận hành. lưới lọc tháo rời dễ dàng để vệ sinh định kỳ, giúp máy duy trì lực hút ổn định lâu dài. Hai đèn LED chiếu sáng tích hợp bảo đảm khu vực nấu luôn đủ sáng.', 'Thương hiệu: Kocher (Đức); Model: K-8872V đen-90cm; Sản xuất tại: Việt Nam; Kiểu lắp: Áp tường; Chất liệu: Kính cường lực; Điện áp: 220V / 50Hz; Tổng công suất (W): 195; Kiểu điều khiển: Phím bấm; Kiểu máy: Kính cong; Lưu lượng hút (m³/h): 1550; Độ ồn (dB): 46; Số cấp tốc độ: 3; Số motor: 1; Công suất motor (W): 195; Loại lọc: Lọc mỡ / Lọc than hoạt tính (khử mùi); Đèn chiếu sáng: LED; Bề rộng (mm): 900; Chất liệu lưới lọc: Inox', 1, 3, 3),
(13, 'HM-CHE-001', 'Máy hút mùi Chef''s EH-R107E3D', 7490000, 4350000, 21, '/img/sp/hm-che-001/1.jpg', NULL, '750 m3/h', 24, 'Máy hút mùi Chef’s model EH‑R107E3D mang đến sức hút mạnh mẽ 750 m³/h, giúp loại bỏ nhanh chóng khói, mùi và dầu mỡ trong không gian bếp, đồng thời tạo điểm nhấn hiện đại cho mọi thiết kế nội thất. Với thương hiệu Chef’s uy tín, sản phẩm được thiết kế để đáp ứng nhu cầu nấu nướng chuyên nghiệp và gia đình, mang lại không gian bếp luôn sạch sẽ và thoáng mát.\nKiểu dáng chữ T tinh tế, kích thước 700 × 350 × 445 mm, mặt trước phủ kính cường lực đen sang trọng và khung inox cao cấp 430, giúp máy hòa nhập hoàn hảo vào tủ bếp sâu 350 mm mà không nhô ra ngoài. Vỏ inox chịu nhiệt và dễ lau chùi, đồng thời bảo vệ các bộ phận bên trong khỏi ăn mòn, mang lại độ bền lâu dài cho sản phẩm.\nCông nghệ động cơ không chổi than (BLDC) tiết kiệm điện năng tới 30‑50 % so với động cơ thông thường, đồng thời vận hành êm ái với độ ồn chỉ 42 dB.', 'Thương hiệu: Chef''s (Việt Nam); Model: EH-R107E3D; Sản xuất tại: Trung Quốc; Kiểu lắp: Áp tường; Chất liệu: Inox; Điện áp: 220V / 50Hz; Tổng công suất (W): 198; Kiểu điều khiển: Cảm ứng / Cảm ứng không chạm (vẫy tay); Kiểu máy: Chữ T; KT máy (R×S×C mm): 700 x 350; Lưu lượng hút (m³/h): 750; Độ ồn (dB): 42; Số cấp tốc độ: 3; Số motor: 1; Công suất motor (W): 198; Loại lọc: Lọc mỡ / Lọc than hoạt tính (khử mùi); Đèn chiếu sáng: LED; Bề rộng (mm): 700; Chất liệu lưới lọc: Inox', 1, 3, 4),
(14, 'MRC-BOS-001', 'Máy rửa chén Bosch SMV6ZCX16E', 33370000, 26220000, 5, '/img/sp/mrc-bos-001/1.jpg', '/img/sp/mrc-bos-001/2.jpg|/img/sp/mrc-bos-001/3.jpg', '14 bộ', 36, 'Máy rửa bát âm toàn phần Bosch SMV6ZCX16E thuộc dòng Serie 6, là mẫu máy rửa bát cao cấp dung tích 14 bộ đồ ăn châu Âu. Thiết kế âm tủ hoàn toàn giúp máy ẩn mình gọn gàng sau cánh tủ bếp, giữ cho không gian bếp liền mạch và sang trọng, đồng thời mang lại hiệu quả làm sạch vượt trội cho gia đình đông thành viên.\nSản phẩm có kích thước cao 81,5 cm, rộng 59,8 cm và sâu 55 cm, dây nguồn dài 175 cm, phù hợp với hốc tủ tiêu chuẩn. Hệ thống RackMatic cho phép điều chỉnh độ cao giỏ rửa, kết hợp giàn rửa nhiều tầng linh hoạt giúp sắp xếp từ đĩa lớn, nồi niêu đến ly cốc mỏng manh một cách khoa học.\nBảng điều khiển cảm ứng đi kèm màn hình hiển thị cho thao tác trực quan và dễ theo dõi tiến trình rửa. SMV6ZCX16E được trang bị 8 chương trình rửa gồm tiết kiệm Eco 50°C, tự động 45-65°C, chương trình thông minh, rửa mạnh 70°C, rửa nhanh 60°C, rửa đồ thủy tinh, rửa yên tĩnh 50°C và chương trình ghi nhớ theo thói quen sử dụng.', 'Thương hiệu: Bosch (Đức); Model: SMV6ZCX16E; Sản xuất tại: Đức; Kiểu lắp: Âm toàn phần; Điện áp: 220-240V / 50-60Hz; Tổng công suất (W): 2400; Độ ồn (dB): 40; Số bộ (place settings): 14; Số chương trình: 14; Công nghệ sấy: Sấy Zeolite; Điện/chu trình (kWh): 0,65; Nước/chu trình (lít): 9; KT (R×S×C mm): 598 x 550 x 815; An toàn: AquaStop chống rò rỉ nước (ống 2 lớp + van tự ngắt)', 1, 4, 1),
(15, 'MRC-BOS-002', 'Máy rửa chén Bosch SMS6ZCI02P', 34900000, 21710000, 3, '/img/sp/mrc-bos-002/1.jpg', NULL, '14 bộ', 36, 'Bosch SMS6ZCI02P thuộc dòng Serie 6 là máy rửa bát độc lập cao cấp, được lắp ráp và nhập khẩu trực tiếp từ Đức. Với dung tích 14 bộ bát đĩa chuẩn châu Âu, sản phẩm đáp ứng nhu cầu của gia đình từ 4‑6 thành viên, mang lại sự sạch sẽ và khô ráo tối ưu cho mọi loại đồ dùng bếp.\nthiết kế với vỏ ngoài bằng thép không gỉ Inox, được phủ lớp chống vân tay AntiFingerprint, giúp bề mặt luôn sáng bóng và dễ vệ sinh. Kích thước tiêu chuẩn 845 mm × 600 mm × 600 mm cho phép lắp đặt linh hoạt ở hầu hết các không gian bếp, có thể đặt độc lập hoặc âm bán phần trong tủ.\nCông nghệ sấy Zeolith độc quyền của Bosch chuyển đổi độ ẩm thành nhiệt, giúp bát đĩa khô hoàn toàn ngay cả đồ nhựa, đồng thời giảm tiêu thụ điện năng so với sấy nhiệt truyền thống. Động cơ EcoSilence Drive vận hành êm ái, độ ồn chỉ 40 dB, mang lại môi trường bếp yên tĩnh.', 'Thương hiệu: Bosch (Đức); Model: SMS6ZCI02P; Sản xuất tại: Đức; Kiểu lắp: Độc lập; Điện áp: 220-240V / 50-60Hz; Tổng công suất (W): 2400; Độ ồn (dB): 40; Số bộ (place settings): 14; Số chương trình: 8; Công nghệ sấy: Sấy Zeolite; Điện/chu trình (kWh): 0,65; Nước/chu trình (lít): 9; KT (R×S×C mm): 600 x 600 x 845; An toàn: AquaStop chống rò rỉ nước, khóa trẻ em', 1, 4, 1),
(16, 'MRC-KAF-001', 'Máy rửa chén Kaff KF-SBL775B New Plus', 26800000, 21180000, 6, '/img/sp/mrc-kaf-001/1.jpg', NULL, '17 bộ', 36, 'Máy rửa chén Kaff KF-SBL775B New Plus là phiên bản màu đen của dòng New Plus cao cấp, dung tích lớn 17 bộ đồ ăn châu Âu, phù hợp cho gia đình đông người hoặc những bữa tiệc cuối tuần nhiều chén đĩa. Với kích thước 598R x 568S x 775mm khi tháo nắp trên, máy lắp âm vừa vặn dưới mặt bàn bếp Việt cao 810mm, đồng thời vẫn có thể đặt độc lập nếu tủ bếp không chừa sẵn khoang.\nThân máy bằng inox sơn tĩnh điện màu đen cao cấp, dáng chữ nhật đứng chắc chắn, tạo điểm nhấn sang trọng và hiện đại cho gian bếp. Khoang rửa bằng thép không gỉ chịu nhiệt tốt, chống ăn mòn và dễ vệ sinh.\nBảng điều khiển cảm ứng cùng màn hình LED hiển thị rõ ràng giúp chọn chương trình chỉ trong vài thao tác chạm. Sản phẩm tích hợp 8 chương trình rửa gồm rửa thông minh tự động, rửa kỹ, rửa thông thường, rửa tiết kiệm ECO, rửa ly, rửa nhanh tráng nước nóng, rửa hoa quả và chương trình rửa diệt khuẩn cho đồ trẻ em.', 'Thương hiệu: Kaff (Đức); Model: KF-SBL775B New Plus; Sản xuất tại: Thái Lan; Kiểu lắp: Độc lập; Điện áp: 220-240V / 50-60Hz; Độ ồn (dB): 48; Số bộ (place settings): 17; Số chương trình: 8; Công nghệ sấy: Sấy khí nóng (PTC); Điện/chu trình (kWh): 0,92; Nước/chu trình (lít): 11.2; KT phủ bì (R×S mm): 598 x 568; KT (R×S×C mm): 598 x 568 x 775; An toàn: Khóa trẻ em, tự khóa máy khi sự cố (ngập nước, va đập, yếu điện, thiếu nước), chống rò nước', 1, 4, 2),
(17, 'MRC-CHE-001', 'Máy rửa chén Chef''s EH-DW401D', 17900000, 13100000, 10, '/img/sp/mrc-che-001/1.jpg', NULL, '15 bộ', 36, 'Máy rửa chén Chef''s EH-DW401D là mẫu máy dung tích lớn của thương hiệu Việt Nam Chef''s, sản xuất tại Trung Quốc, hướng tới các gia đình cần rửa nhiều bát đĩa mỗi ngày nhưng vẫn muốn thiết bị vận hành êm và dễ sử dụng. Máy có dung tích 15 bộ châu Âu, tương đương 3 – 4 bữa cơm Việt, đủ cho lượng chén bát, xoong nồi của một gia đình đông người.\nMáy có thể lắp âm tủ hoặc đặt độc lập với kích thước 845 x 600 x 600 mm, màu inox xám sáng bóng dễ phối với nhiều phong cách bếp, trọng lượng 49 kg. Khoang rửa làm bằng inox với 3 giàn rửa được bố trí riêng cho thìa đũa, bát đĩa và xoong nồi, giúp phân loại đồ hợp lý để nâng cao hiệu quả làm sạch.\nMáy điều khiển bằng phím cơ kết hợp màn hình LED hiển thị chế độ rửa và thời gian hoạt động. EH-DW401D được trang bị 8 chương trình rửa tự động gồm Auto, Intensive, Universal, ECO, Glass, 90min, Rapid và Pre-wash, cho phép chọn chế độ đúng với loại đồ và mức độ bẩn thực tế.', 'Thương hiệu: Chef''s (Việt Nam); Model: EH-DW401D; Sản xuất tại: Trung Quốc; Kiểu lắp: Độc lập / Âm toàn phần; Điện áp: 220V / 50Hz; Tổng công suất (W): 2100; Độ ồn (dB): 42; Số bộ (place settings): 15; Số chương trình: 8; Công nghệ sấy: Sấy khí nóng, Tự động mở cửa; Điện/chu trình (kWh): 0,95; Nước/chu trình (lít): 12; KT (R×S×C mm): 600 x 600 x 845; An toàn: Khóa trẻ em, chỉ báo muối', 1, 4, 4),
(18, 'LN-BOS-001', 'Lò nướng Bosch HBG536ES3', 18900000, 15370000, 7, '/img/sp/ln-bos-001/1.jpg', '/img/sp/ln-bos-001/2.jpg|/img/sp/ln-bos-001/3.jpg', '71 lít', 36, 'Lò nướng âm tủ Bosch HBG536ES3 thuộc dòng Serie 6, là bước nâng cấp rõ rệt về tiện nghi so với các dòng Series thấp hơn, dành cho những gia đình nấu nướng thường xuyên và muốn thiết bị hỗ trợ nhiều hơn. Sản phẩm mang thương hiệu Bosch xuất xứ Đức, được sản xuất tại Tây Ban Nha và bảo hành 36 tháng.\nVề ngoại hình, lò hoàn thiện bằng thép không gỉ kết hợp mặt kính, tạo phong cách châu Âu hiện đại dễ phối hợp với các thiết bị bếp khác. Kiểu lắp âm tủ, đặt được ở đế tủ hoặc tủ cao tùy bố cục bếp.\nKích thước sản phẩm 595 x 594 x 548 mm với khoang khoét tủ 585-595 x 560-568 x 550 mm, khối lượng 34,7 kg. Bảng điều khiển gồm núm xoay kết hợp màn hình LCD trắng hiển thị rõ ràng, giúp người dùng nắm được nhiệt độ và thời gian mà không cần đoán.\nCông nghệ khí nóng 3D là điểm cốt lõi, phân bổ nhiệt đồng đều trên nhiều tầng để thực phẩm chín đều từ trong ra ngoài, cho phép nướng nhiều khay cùng lúc.', 'Thương hiệu: Bosch (Đức); Model: HBG536ES3; Sản xuất tại: Tây Ban Nha; Kiểu lắp: Âm tủ; Chất liệu: Inox / Men chống dính (khoang lò); Điện áp: 220-240V / 50-60Hz; Tổng công suất (W): 3400; Kiểu điều khiển: Núm xoay; KT (R×S×C mm): 594 x 548 x 595; Chất liệu khoang lò: Men xúc tác (Catalytic); Yêu cầu đấu nối: Cầu chì 16 A, không có phích cắm — cần aptomat riêng; Công suất nướng (W): 2700; Dung tích (lít): 71; Số chức năng nướng: 10; Dải nhiệt (°C): 50-275; Công nghệ: 3D Hot-air phân bổ nhiệt đồng đều; Tự làm sạch: Xúc tác (Catalytic); Tên thương mại làm sạch: EcoClean Direct; Chức năng: Nướng trên/dưới, nướng pizza, làm nóng nhẹ, làm nóng thông thường, nướng thường, EcoClean Direct + thủy phân, Gia nhiệt nhanh, Khóa trẻ em, Kính cửa tháo rời, Cảm biến quá nhiệt, cửa kính 2 lớp cách nhiệt, hẹn giờ tự động ngắt; KT khoét (R×S×C mm): 560 x 550 x 585; An toàn: Cảm biến quá nhiệt, cửa kính 2 lớp cách nhiệt, hẹn giờ tự động ngắt', 1, 5, 1),
(19, 'LN-KAF-001', 'Lò nướng Kaff KF-T90S', 20800000, 15070000, 9, '/img/sp/ln-kaf-001/1.jpg', '/img/sp/ln-kaf-001/2.jpg', '67 lít', 36, 'Lò nướng Kaff KF-T90S là mẫu lò nướng đối lưu lắp âm tủ dung tích 67 lít với 12 chức năng nướng, dành cho những gia đình có nhu cầu nấu nướng đa dạng và thường xuyên làm bánh tại nhà. Thiết kế âm tủ chỉ để hở mặt trước, toàn bộ khoang lắp chìm vào tủ bếp, giúp gian bếp gọn gàng và giữ nhiệt độ lò ổn định trong suốt quá trình hoạt động.\nVề ngoại hình, lò dùng mặt kính đen phủ bên ngoài với viền thép chắc chắn bao quanh. Cửa lò gồm 3 lớp kính cách nhiệt, vừa cho phép quan sát rõ quá trình nướng bên trong, vừa hạn chế thất thoát nhiệt và giảm nguy cơ bỏng khi vô tình chạm vào bề mặt cửa.\nKhoang lò được tráng men chịu nhiệt, ít bám dính nên việc vệ sinh sau khi dùng khá đơn giản. Kích thước sản phẩm 595C x 595R x 575S mm với kích thước âm tủ 590C x 560R x 595S mm là các thông số tiêu chuẩn, dễ phối vào hệ tủ bếp.\nVề hiệu năng, tổng công suất 3450W kết hợp chế độ nướng đối lưu giúp luồng khí nóng tuần hoàn liên tục trong khoang.', 'Thương hiệu: Kaff (Đức); Model: KF-T90S; Sản xuất tại: Malaysia; Kiểu lắp: Âm tủ; Chất liệu: Kính; Điện áp: 220-240V; Tổng công suất (W): 3450; Kiểu điều khiển: Cảm ứng; KT (R×S×C mm): 595 x 575 x 595; Số lớp kính cửa: 3; Dung tích (lít): 67; Số chức năng nướng: 12; Dải nhiệt (°C): 50-250; Công nghệ: Nướng đối lưu; Tự làm sạch: Xúc tác (Catalytic); Chức năng: 12 chức năng nướng; KT khoét (R×S×C mm): 590 x 560 x 550; An toàn: Khóa trẻ em, Tự động tắt khi không sử dụng', 1, 5, 2),
(20, 'LN-KOC-001', 'Lò nướng Kocher KOEU-71S14F', 22650000, 13350000, 12, '/img/sp/ln-koc-001/1.jpg', NULL, '71 lít', 36, 'Lò nướng âm tủ Kocher KOEU-71S14F là phiên bản nâng cấp trong dòng lò 71 lít của Kocher, nổi bật với 14 chương trình nấu nướng tự động và khả năng tự làm sạch. Sản phẩm mang thương hiệu Kocher xuất xứ Đức, được sản xuất tại Việt Nam, bảo hành chính hãng 36 tháng.\nVề thiết kế, lò mang phong cách châu Âu hiện đại với thân vỏ bằng thép không gỉ siêu bền, dễ vệ sinh và giữ được vẻ sáng bóng theo thời gian. Cửa lò sử dụng mặt kính 3 lớp cách nhiệt chịu lực, bảo vệ người dùng khỏi nguy cơ bỏng khi chạm phải và giúp giữ nhiệt bên trong hiệu quả hơn.\nKiểu mở phía trước cùng thiết kế lắp âm tủ tạo sự liền mạch và gọn gàng cho căn bếp. Kích thước sản phẩm 595 x 595 x 575 mm theo chiều cao, rộng và sâu.\nKhoang lò 71 lít cho phép chế biến nhiều loại thực phẩm cùng lúc mà vẫn đảm bảo chín đều.', 'Thương hiệu: Kocher (Đức); Model: KOEU-71S14F; Sản xuất tại: Việt Nam; Kiểu lắp: Âm tủ; Chất liệu: Men chống dính (khoang lò); Điện áp: 220-240V / 50Hz; Tổng công suất (W): 2300; Kiểu điều khiển: Cảm ứng / Cơ; KT (R×S×C mm): 595 x 575 x 595; Chất liệu khoang lò: Thép tráng men; Số lớp kính cửa: 3; Dung tích (lít): 71; Số chức năng nướng: 14; Công nghệ: Khí nóng 3D (3D hot air); Chức năng: 14 chức năng tự động; An toàn: Khóa an toàn trẻ em, kính 3 lớp chịu nhiệt, quạt tự làm mát', 1, 5, 3),
(21, 'LN-CHE-001', 'Lò nướng Chef''s EH-BO600E', 16900000, 10660000, 14, '/img/sp/ln-che-001/1.jpg', NULL, '72 lít', 36, 'Lò nướng âm tủ Chef''s EH-BO600E là mẫu lò dung tích lớn dành cho những gia đình nấu nướng nhiều, mong muốn một thiết bị đa năng nhưng vẫn dễ thao tác. Sản phẩm mang thương hiệu Chef''s với xuất xứ thương hiệu Việt Nam, được sản xuất tại Trung Quốc và bảo hành chính hãng 36 tháng theo hình thức bảo hành điện tử.\nVề thiết kế, lò được thiết kế theo tiêu chuẩn châu Âu với thiết kế âm tủ giúp tiết kiệm diện tích, đồng thời tăng tính thẩm mỹ và sự gọn gàng cho không gian bếp. Thân lò hoàn thiện bằng chất liệu inox chống gỉ cao cấp kết hợp mặt kính, được gia công tỉ mỉ tới từng chi tiết.\nCửa lò sử dụng kính 4 lớp, ngăn nhiệt lượng thất thoát ra ngoài, vừa giữ hiệu năng nấu nướng vừa hạn chế hao phí điện năng và giảm nguy cơ bỏng khi vô tình chạm phải. Kích thước sản phẩm khoảng 595 x 565 x 595 mm.\nBên trong lò có đèn chiếu sáng tiện lợi để quan sát món ăn trong suốt quá trình nướng.', 'Thương hiệu: Chef''s (Việt Nam); Model: EH-BO600E; Sản xuất tại: Trung Quốc; Kiểu lắp: Âm tủ; Chất liệu: Kính; Tổng công suất (W): 3200; Kiểu điều khiển: Cảm ứng / Núm xoay; KT (R×S×C mm): 595 x 565 x 595; Số lớp kính cửa: 4; Dung tích (lít): 72; Số chức năng nướng: 11; Dải nhiệt (°C): 30-250; Công nghệ: Tự làm sạch nhiệt phân (Pyrolytic); Chức năng: Tự làm sạch, Quick Heat, 11 chương trình, kính 4 lớp, Khóa trẻ em; An toàn: Khóa trẻ em', 1, 5, 4),
(22, 'LVS-BOS-001', 'Lò vi sóng Bosch BEL524MB2', 16900000, 14270000, 5, '/img/sp/lvs-bos-001/1.jpg', '/img/sp/lvs-bos-001/2.jpg|/img/sp/lvs-bos-001/3.jpg', '20 lít', 24, 'Lò vi sóng âm tủ Bosch BEL524MB2 thuộc dòng Serie 6, là lựa chọn dành cho những căn bếp đề cao sự đồng bộ và gọn gàng. Với thiết kế âm tủ tiêu chuẩn, thiết bị được lắp liền mạch vào hệ tủ bếp, giúp mặt bằng bếp thoáng hơn so với lò đặt bàn, đồng thời giữ được tổng thể liền khối cho khu vực nấu nướng.\nVề thẩm mỹ, sản phẩm sử dụng mặt kính đen kết hợp khoang lò bằng inox với đáy kính. Mặt kính đen dễ lau chùi và phù hợp với nhiều phong cách nội thất từ hiện đại đến tối giản, trong khi khoang inox giúp truyền nhiệt đều và hạn chế bám bẩn.\nKích thước sản phẩm 382 x 594 x 317 mm, kích thước hộc tủ yêu cầu 382 x 560 x 300 mm, khối lượng 17,2 kg. BEL524MB2 có dung tích 20 lít, phù hợp với nhu cầu hằng ngày của gia đình nhỏ: hâm nóng thức ăn, rã đông thực phẩm và chế biến các món đơn giản.', 'Thương hiệu: Bosch (Đức); Model: BEL524MB2; Sản xuất tại: Trung Quốc; Kiểu lắp: Âm tủ; Điện áp: 220-230V / 50Hz; Tổng công suất (W): 1270; Kiểu điều khiển: Cảm ứng trượt (Slider); KT (R×S×C mm): 594 x 317 x 382; Dung tích (lít): 20; Tự làm sạch: Có (thủy phân/Hydrolytic); Loại lò: Vi sóng + nướng; Kiểu khoang: Có đĩa quay; Công suất vi sóng (W): 800; Số mức công suất: 5; An toàn: Khóa trẻ em, tự động tắt', 1, 6, 1),
(23, 'LVS-KAF-001', 'Lò vi sóng Kaff KF-EM036ALMW', 9800000, 7100000, 11, '/img/sp/lvs-kaf-001/1.jpg', NULL, '36 lít', 36, 'Lò vi sóng Kaff KF-EM036ALMW là mẫu lò để bàn kết hợp chức năng nướng, hướng đến những gia đình muốn một thiết bị đa năng thay vì chỉ dùng để hâm nóng đơn thuần. Với dung tích 36 lít, đây là mức dung tích lớn trong nhóm lò vi sóng để bàn, đủ chỗ cho khay đĩa cỡ lớn và phù hợp với nhu cầu nấu nướng của gia đình đông thành viên.\nSản phẩm có kích thước 519 x 426 x 315 mm, thiết kế đặt bàn nên dễ bố trí trên mặt bếp hoặc kệ mà không cần cải tạo hệ tủ. Vòng ngoài hoàn thiện chỉn chu, bề mặt hạn chế bám dấu vân tay, giúp lò luôn trông sạch sẽ và góp phần tạo vẻ gọn gàng cho khu vực nấu nướng.\nBên trong, đĩa xoay thủy tinh chịu nhiệt đường kính 315 mm giúp thực phẩm quay đều và chín đồng nhất. Về khả năng chế biến, KF-EM036ALMW là lò 2 trong 1: vừa vi sóng vừa nướng, công suất 1000W.', 'Thương hiệu: Kaff (Đức); Model: KF-EM036ALMW; Sản xuất tại: Thái Lan; Kiểu lắp: Để bàn; Điện áp: 220-240V / 50-60Hz; KT (R×S×C mm): 519 x 426 x 315; Dung tích (lít): 36; Loại lò: Vi sóng + nướng; Công suất vi sóng (W): 1000; Số mức công suất: 11; An toàn: Khóa trẻ em', 1, 6, 2),
(24, 'LVS-KOC-001', 'Lò vi sóng Kocher KMEU-1025A', 13900000, 8130000, 13, '/img/sp/lvs-koc-001/1.jpg', NULL, '25 lít', 24, 'Lò vi sóng âm tủ Kocher KMEU-1025A là thiết bị dành cho những căn bếp hiện đại cần một giải pháp hâm nóng, rã đông và nấu nhanh gọn gàng mà không chiếm chỗ trên mặt bàn. Sản phẩm mang thương hiệu Kocher xuất xứ Đức, được sản xuất tại Malaysia và bảo hành 24 tháng.\nVề thiết kế, lò có kiểu dáng âm tủ tinh gọn với mặt kính đen liền mạch và bảng điều khiển LCD hiển thị rõ ràng, dễ thao tác. Kích thước sản phẩm 595 rộng x 351 sâu x 390 cao mm với khoang lắp đặt 600 x 550 x 378 mm, phù hợp với các hệ tủ bếp tiêu chuẩn theo phong cách tối giản châu Âu.\nCửa lò bằng kính lớn giúp quan sát quá trình nấu thuận tiện mà không cần mở cửa làm thất thoát nhiệt. Khoang lò dung tích 25 lít đủ rộng để đặt các đĩa hoặc khay thực phẩm cỡ lớn, đáp ứng nhu cầu của gia đình đông người hoặc những lần chuẩn bị nhiều món cùng lúc.\nĐĩa xoay thủy tinh giúp thực phẩm chín và nóng đều hơn.', 'Thương hiệu: Kocher (Đức); Model: KMEU-1025A; Sản xuất tại: Malaysia; Kiểu lắp: Âm tủ; Điện áp: 220-240V / 50Hz; Kiểu điều khiển: Cảm ứng; KT (R×S×C mm): 595 x 351 x 390; Dung tích (lít): 25; Loại lò: Vi sóng + nướng + đối lưu; Công suất vi sóng (W): 900; An toàn: Khóa an toàn trẻ em, cửa kính cách nhiệt, quạt làm mát', 1, 6, 3),
(25, 'LVS-CHE-001', 'Lò vi sóng Chef''s EH-MW801B', 9800000, 7170000, 18, '/img/sp/lvs-che-001/1.jpg', NULL, '25 lít', 36, 'Lò vi sóng kết hợp nướng Chef''s EH-MW801B là phiên bản tông đen sang trọng trong dòng lò âm tủ 25 lít của Chef''s, thương hiệu Việt Nam với sản phẩm được sản xuất tại Trung Quốc. thiết kế, mang hơi hướng châu Âu, phù hợp cho những căn bếp muốn có một thiết bị vừa hâm nóng nhanh vừa nướng được đa dạng món ăn.\nSản phẩm có kích thước 388 x 592 x 401 mm, khuyến khích lắp âm tủ để tiết kiệm diện tích, nhưng vẫn có thể đặt dương tùy nhu cầu bố trí. Mặt trước màu đen kết hợp cửa kính hai lớp cách nhiệt viền inox tạo tổng thể cân đối và chắc chắn.\nVề chất liệu, khoang lò được tráng men inox an toàn và dễ vệ sinh, vỏ lò làm bằng thép không gỉ kết hợp kính trong suốt chịu lực, cho độ bền tốt theo thời gian. Đường kính đĩa xoay 31,5 cm cùng dung tích 25 lít đáp ứng nhu cầu ăn uống của hộ gia đình từ 4 đến 6 thành viên.\nTrọng lượng sản phẩm 19,5 kg.', 'Thương hiệu: Chef''s (Việt Nam); Model: EH-MW801B; Sản xuất tại: Trung Quốc; Kiểu lắp: Âm tủ / Để bàn; Kiểu điều khiển: Cảm ứng; KT (R×S×C mm): 592 x 401 x 388; Công suất nướng (W): 1200; Dung tích (lít): 25; Dải nhiệt (°C): 30-250; Loại lò: Vi sóng + nướng; Công suất vi sóng (W): 900; Số mức công suất: 5; An toàn: đóng cửa tự động', 1, 6, 4),
(26, 'BDT-BOS-002', 'Bếp từ Bosch PID651DC5E', 20610000, 16460000, 9, '/img/sp/bdt-bos-002/1.jpg', '/img/sp/bdt-bos-002/2.jpg|/img/sp/bdt-bos-002/3.jpg', '7400W', 36, 'Bếp từ Bosch PID651DC5E mang lại trải nghiệm nấu ăn hiện đại nhờ công nghệ điện từ tiên tiến và thiết kế. Với công suất tổng 7400 W và ba vùng nấu độc lập, sản phẩm đáp ứng nhanh chóng mọi nhu cầu từ hầm súp, chiên xào đến đun sôi, đồng thời giúp tiết kiệm năng lượng so với bếp gas truyền thống.\nMặt bếp được làm từ gốm thủy tinh Schott Ceran màu đen, chịu nhiệt lên tới 10 °C và có bề mặt vát nghiêng 4 cạnh, giúp nước bắn trượt nhanh và dễ dàng lau chùi. Kiểu lắp âm và kích thước khoét đá 560‑562 mm x 490‑502 mm x 59 mm phù hợp với hầu hết các bếp đá, trong khi bảng điều khiển cảm ứng DirectSelect dài 30 cm cho phép người dùng lựa chọn mức nhiệt chỉ bằng một chạm.\nCông nghệ PerfectFry tích hợp cảm biến chiên xào liên tục điều chỉnh nhiệt độ, giúp thực phẩm đạt độ chín vàng giòn mà không bị cháy khét. DirectSelect Premium cung cấp 17 mức gia nhiệt chi tiết, cho phép tùy chỉnh chính xác từng vùng nấu.', 'Thương hiệu: Bosch (Đức); Model: PID651DC5E; Sản xuất tại: Tây Ban Nha; Kiểu lắp: Âm tủ; Chất liệu: Kính; Điện áp: 220V; Tổng công suất (W): 7400; Kiểu điều khiển: Cảm ứng; Số vùng nấu: 3; KT mặt kính (R×S mm): 592 x 522; KT khoét đá (R×S mm): 560 x 490; Công suất từng vùng (W): 3300 + 2200 + 1400; Booster: Có; CS Booster tối đa (W): 4400; Mặt kính: Schott Ceran (Đức); Vùng nấu đặc biệt: Vùng nấu mở rộng (FlexZone); Công nghệ bo mạch: Inverter; An toàn: Khoá trẻ em, tự ngắt, cảnh báo nhiệt dư, an toàn tràn', 1, 1, 1),
(27, 'BDT-KAF-002', 'Bếp từ Kaff KF-FL68II NEW PLUS', 17800000, 11720000, 5, '/img/sp/bdt-kaf-002/1.jpg', NULL, '4400W', 36, 'Bếp từ đôi Kaff KF-FL68II New Plus mang đến trải nghiệm nấu nướng hiện đại với công suất tối đa 4400W, chia thành hai vùng 2200W mỗi vùng. Mặt kính Schott Ceran siêu bền, chịu lực và chịu sốc nhiệt, được thiết kế mỏng gọn, lắp âm tạo không gian bếp tinh tế, đồng thời dễ dàng vệ sinh.\nĐặc biệt, bếp được trang bị công nghệ Inverter biến tần giúp tiết kiệm điện năng lên tới 40%, cùng với 9 dãy công suất và chức năng Booster nâng công suất lên 3200W khi cần nấu nhanh.\\n\\nThiết kế cảm ứng slider trực tiếp trên mặt bếp mang lại trải nghiệm thao tác mượt mà, nhanh nhạy. Hệ thống điều khiển thông minh cho phép người dùng tùy chỉnh nhiệt độ, thời gian, và các chế độ nấu như hâm, chiên xào, rã đông, sôi liu riu.', 'Thương hiệu: Kaff (Đức); Model: KF-FL68II NEW PLUS; Sản xuất tại: Malaysia; Kiểu lắp: Âm tủ; Chất liệu: Kính; Điện áp: 220-240V / 50-60Hz; Tổng công suất (W): 4400; Kiểu điều khiển: Cảm ứng trượt (Slider); Số vùng nấu: 2; KT mặt kính (R×S mm): 730 x 430; KT khoét đá (R×S mm): 680 x 390; Công suất từng vùng (W): 2200 + 2200; Booster: Có; CS Booster tối đa (W): 3200; Mặt kính: Schott Ceran (Đức); Công nghệ bo mạch: Inverter; An toàn: Khoá trẻ em, hẹn giờ 99 phút, tạm dừng, tự tắt khi quá nhiệt/tràn, cảnh báo nhiệt dư', 1, 1, 2),
(28, 'BHN-KAF-003', 'Bếp đôi từ hồng ngoại Kaff KF-FL108', 20800000, 16440000, 0, '/img/sp/bhn-kaf-003/1.jpg', '/img/sp/bhn-kaf-003/2.jpg|/img/sp/bhn-kaf-003/3.jpg', '4300W', 36, 'Bếp điện từ Kaff KF-FL108 là mẫu bếp hai vùng nấu kết hợp một vùng từ và một vùng hồng ngoại, nhập khẩu nguyên chiếc từ CHLB Đức. Điểm nhận diện của model này là phần bo viền hợp kim nhôm cao cấp chạy quanh mặt kính, vừa tăng vẻ chắc chắn vừa bảo vệ cạnh kính khỏi va đập trong quá trình sử dụng.\nMặt bếp làm từ kính Schott Ceran của Đức, chất liệu gốm thủy tinh nổi tiếng với khả năng chịu lực, chịu nhiệt và chống sốc nhiệt tốt, bề mặt bóng sáng, bền bỉ và dễ lau chùi khi bám bẩn. Bếp có thể lắp âm hoặc đặt nổi tùy không gian, tông màu đen sang trọng dễ hòa hợp với nhiều phong cách tủ bếp.\nKích thước mặt kính 730x430 mm, kích thước khoét đá 680x380 mm là thông số phổ thông nên thuận tiện khi lắp mới hoặc thay thế bếp cũ. Hai vùng nấu có công suất 2200W mỗi bên, chia thành 10 mức gia nhiệt để người nấu chọn chính xác mức nhiệt cho từng món.', 'Thương hiệu: Kaff (Đức); Model: KF-FL108; Sản xuất tại: Đức; Kiểu lắp: Âm tủ; Chất liệu: Kính; Tổng công suất (W): 4300; Kiểu điều khiển: Cảm ứng trượt (Slider); Số vùng nấu: 2; KT mặt kính (R×S mm): 730 x 430; KT khoét đá (R×S mm): 680 x 380; Công suất từng vùng (W): 2300 + 2000; Booster: Có; CS Booster tối đa (W): 3700; Mặt kính: Schott Ceran (Đức); An toàn: Overflow, Overheat, Child lock, Timer', 1, 2, 2),
(29, 'HM-BOS-002', 'Máy hút mùi Bosch DFT63CA61B', 6900000, 5490000, 2, '/img/sp/hm-bos-002/1.jpg', '/img/sp/hm-bos-002/2.jpg|/img/sp/hm-bos-002/3.jpg', '310 m3/h', 36, 'Máy hút mùi Bosch DFT63CA61B là mẫu hút mùi âm tủ khổ 60 cm, phù hợp với những căn bếp có tủ trên và cần một thiết bị gọn gàng nhưng vẫn đảm bảo hiệu quả khử khói mùi hằng ngày. Sản phẩm thuộc thương hiệu Bosch của Đức, được sản xuất tại Thổ Nhĩ Kỳ.\nMáy có kiểu lắp âm tủ với kích thước thiết bị 175 x 598 x 300 mm, kích thước lắp đặt 135 x 598 x 280 mm nên dễ dàng giấu gọn vào khoang tủ bếp, chỉ lộ phần bề mặt hút. Thân máy làm từ thép không gỉ kết hợp kính đen, hoàn thiện tông inox bạc sang trọng, vừa bền trong môi trường nhiều hơi nước và dầu mỡ, vừa thuận tiện khi lau chùi.\nVề khả năng hút, thiết bị sử dụng động cơ công suất 181 W, cho công suất hút 310 m3/h với 3 cấp độ để người dùng điều chỉnh theo lượng khói thực tế. Mức thấp phù hợp các món luộc, hấp. mức cao dành cho những bữa chiên xào nhiều dầu mỡ hoặc món nặng mùi.\nĐộ ồn khi hoạt động ở mức 67 dBA.', 'Thương hiệu: Bosch (Đức); Model: DFT63CA61B; Sản xuất tại: Thổ Nhĩ Kỳ; Kiểu lắp: Âm tủ; Chất liệu: Inox / Thép sơn tĩnh điện; Điện áp: 220-240V; Tổng công suất (W): 181; Kiểu điều khiển: Phím bấm; Lưu lượng hút (m³/h): 310; Độ ồn (dB): 67; Số cấp tốc độ: 3; Số motor: 1; Công suất motor (W): 181; Loại lọc: Lọc mỡ; Đèn chiếu sáng: LED; Bề rộng (mm): 600', 1, 3, 1),
(30, 'MRC-KOC-001', 'Máy rửa chén Kocher MRB-X15S', 17500000, 11950000, 7, '/img/sp/mrc-koc-001/1.jpg', '/img/sp/mrc-koc-001/2.jpg', '17 bộ', 24, 'Máy rửa chén Kocher MRB-X15S là mẫu máy rửa chén dung tích 17 bộ, thuộc dòng MRB-X15 của Kocher, phiên bản hoàn thiện màu bạc. Dung tích 17 bộ phù hợp với gia đình đông người hoặc những bữa cơm nhiều món, cho phép rửa gọn lượng chén đĩa của cả ngày trong một chu trình.\nBản màu bạc là lựa chọn cho căn bếp dùng nhiều chi tiết inox hoặc tông sáng. Sản phẩm thuộc thương hiệu Kocher, xuất xứ thương hiệu Đức và được sản xuất tại Việt Nam.', 'Thương hiệu: Kocher (Đức); Model: MRB-X15S; Sản xuất tại: Việt Nam; Kiểu lắp: Độc lập / Âm toàn phần; Điện áp: 220-240V / 50Hz; Độ ồn (dB): 49; Số bộ (place settings): 17; Số chương trình: 7; Công nghệ sấy: Sấy tăng cường; Điện/chu trình (kWh): 0,86; Nước/chu trình (lít): 9; KT phủ bì (R×S mm): 598 x 590; KT (R×S×C mm): 598 x 590 x 805; An toàn: Khóa trẻ em, hẹn giờ 24h, cảm biến cảnh báo lỗi', 1, 4, 3),
(31, 'MRC-BOS-003', 'Máy rửa chén Bosch SMS4ECI01P', 25900000, 20610000, 4, '/img/sp/mrc-bos-003/1.jpg', '/img/sp/mrc-bos-003/2.jpg|/img/sp/mrc-bos-003/3.jpg', '13 bộ', 36, 'Máy rửa chén độc lập Bosch SMS4ECI01P Serie 4 là giải pháp lý tưởng cho gia đình hiện đại mong muốn tối ưu thời gian và công sức nội trợ. Sở hữu thiết kế, khoang rửa rộng rãi cùng nhiều công nghệ rửa và sấy tiên tiến, sản phẩm giúp chén bát sạch sâu, khô ráo và an toàn cho sức khỏe người dùng.\nMáy có kiểu dáng độc lập chắc chắn, lớp vỏ thép sơn tĩnh điện kết hợp cửa thép không gỉ sáng bóng, vừa bền bỉ vừa tạo điểm nhấn cho gian bếp. Nhờ thiết kế này, người dùng có thể bố trí máy ở nhiều vị trí khác nhau mà không phụ thuộc vào tủ bếp.\nKích thước tiêu chuẩn cao 84,5 cm, rộng 60 cm và sâu 60 cm giúp việc lắp đặt trở nên đơn giản. Hệ thống giỏ VarioFlex cùng khay trên điều chỉnh được độ cao cho phép linh hoạt thay đổi không gian chứa, thuận tiện khi cần rửa nồi chảo lớn hay ly cốc cao.', 'Thương hiệu: Bosch (Đức); Model: SMS4ECI01P; Sản xuất tại: Đức; Kiểu lắp: Độc lập; Điện áp: 220-240V / 50-60Hz; Tổng công suất (W): 2400; Độ ồn (dB): 46; Số bộ (place settings): 13; Số chương trình: 6; Công nghệ sấy: Sấy tăng cường, Tự động mở cửa; Điện/chu trình (kWh): 0,84; Nước/chu trình (lít): 9.5; KT (R×S×C mm): 600 x 600 x 845; An toàn: AquaStop chống rò rỉ nước, khóa trẻ em, tự vệ sinh máy', 1, 4, 1),
(32, 'LN-BOS-002', 'Lò nướng Bosch HBA514BS3', 15900000, 13540000, 3, '/img/sp/ln-bos-002/1.jpg', '/img/sp/ln-bos-002/2.jpg|/img/sp/ln-bos-002/3.jpg', '71 lít', 36, 'Lò nướng âm tủ Bosch HBA514BS3 thuộc dòng Series 4, là lựa chọn quen thuộc cho những căn bếp muốn nâng cấp lên chuẩn thiết bị châu Âu mà vẫn giữ được mức đầu tư hợp lý. Sản phẩm mang thương hiệu Bosch của Đức, được sản xuất tại Ba Lan và bảo hành 36 tháng.\nVề thiết kế, HBA514BS3 hoàn thiện bằng thép không gỉ kết hợp cửa kính đen, tạo thiết kế và dễ hòa hợp với mọi phong cách bếp hiện đại. Kiểu lắp âm tủ giúp mặt bếp trở nên gọn gàng, liền mạch.\nKích thước sản phẩm 595 x 594 x 548 mm phù hợp khoang tủ tiêu chuẩn 585-595 x 560-568 x 550 mm. Hệ thống núm xoay dạng pop-out kết hợp phím bấm vừa thao tác nhanh, vừa dễ lau chùi mặt trước vì núm có thể thu gọn khi không dùng.\nKhoang lò dung tích 71 lít với lớp tráng men bên trong cho không gian rộng rãi để chế biến nhiều món cùng lúc, từ gà nguyên con, pizza cỡ lớn tới các mẻ bánh nhiều tầng.', 'Thương hiệu: Bosch (Đức); Model: HBA514BS3; Sản xuất tại: Ba Lan; Kiểu lắp: Âm tủ; Chất liệu: Kính; Điện áp: 220-240V / 50-60Hz; Tổng công suất (W): 3400; Kiểu điều khiển: Phím bấm / Núm xoay; KT (R×S×C mm): 594 x 548 x 595; Số lớp kính cửa: 3; Yêu cầu đấu nối: Cầu chì 16 A, không có phích cắm — cần aptomat riêng; Công suất nướng (W): 2700; Dung tích (lít): 71; Số chức năng nướng: 8; Dải nhiệt (°C): 50-275; Công nghệ: 3D Hotair (đối lưu khí nóng 3D); Tự làm sạch: Thủy phân (Hydrolytic); Chức năng: 8 chế độ nướng; KT khoét (R×S×C mm): 560 x 550 x 585; An toàn: Khóa trẻ em, tự động ngắt khi đạt nhiệt độ, cửa kính cách nhiệt 3 lớp', 1, 5, 1),
(33, 'LN-KAF-002', 'Lò nướng Kaff KF-901', 14600000, 10580000, 20, '/img/sp/ln-kaf-002/1.jpg', NULL, '60 lít', 36, 'Lò nướng Kaff KF-901 là mẫu lò nướng âm tủ dung tích 60 lít với 9 chức năng nướng, dành cho những gia đình yêu thích làm bánh và chế biến các món nướng tại nhà. Thiết kế âm tủ chỉ để lộ mặt trước, toàn bộ phần khoang lắp chìm vào tủ bếp, giúp căn bếp gọn gàng đồng thời giữ nhiệt độ lò ổn định khi hoạt động.\nVề ngoại hình, lò sử dụng mặt kính đen cao cấp kết hợp viền thép chắc chắn, cửa kính nhiều lớp cách nhiệt giúp quan sát bên trong mà vẫn hạn chế thất thoát nhiệt. Tay nắm cửa dạng thanh ngang bằng inox không gỉ cho thao tác mở nhẹ nhàng, chắc tay và bền theo thời gian.\nĐèn chiếu sáng bên trong khoang giúp theo dõi món ăn mà không cần mở cửa lò, tránh làm tụt nhiệt giữa chừng. Về hiệu năng, KF-901 có tổng công suất 3600W cùng 9 chức năng nướng, trong đó nổi bật là chức năng nướng đối lưu.', 'Thương hiệu: Kaff (Đức); Model: KF-901; Sản xuất tại: Malaysia; Kiểu lắp: Âm tủ; Chất liệu: Inox; Điện áp: 220-240V; Tổng công suất (W): 3600; Kiểu điều khiển: Núm xoay / Cơ; KT (R×S×C mm): 595 x 550 x 595; Dung tích (lít): 60; Số chức năng nướng: 9; Công nghệ: Catalytic self-cleaning; Tự làm sạch: Xúc tác (Catalytic); Chức năng: 9 chức năng nướng; An toàn: Khóa trẻ em', 1, 5, 2),
(34, 'LVS-BOS-002', 'Lò vi sóng Bosch FEL053MS1M', 5900000, 5490000, 6, '/img/sp/lvs-bos-002/1.jpg', '/img/sp/lvs-bos-002/2.jpg|/img/sp/lvs-bos-002/3.jpg', '25 lít', 24, 'Lò vi sóng Bosch FEL053MS1M thuộc dòng Serie 2, là mẫu lò vi sóng độc lập dành cho những gia đình cần một thiết bị linh hoạt về vị trí lắp đặt. Khác với lò âm tủ, sản phẩm có thể đặt trực tiếp trên bàn bếp, kệ hoặc bố trí trong tủ tùy theo không gian, rất phù hợp khi căn bếp đã hoàn thiện và không muốn cải tạo hệ tủ.\nVề thiết kế, lò hoàn thiện bằng mặt kính đen phối inox, tạo vẻ ngoài chắc chắn và hiện đại, dễ phối với các thiết bị bếp khác. Bề mặt kính dễ lau chùi sau khi nấu, còn phần inox mang lại cảm giác cao cấp cho tổng thể sản phẩm.\nCửa lò sử dụng bản lề trái, mở sang phải, thuận tiện với đa số bố cục bếp thông dụng. Sản phẩm được trang bị công nghệ Inverter, giúp điều chỉnh công suất mượt hơn thay vì bật tắt liên tục như lò thông thường, nhờ đó thực phẩm được làm nóng đều và giữ được độ ẩm tốt hơn.', 'Thương hiệu: Bosch (Đức); Model: FEL053MS1M; Sản xuất tại: Trung Quốc; Kiểu lắp: Để bàn; Điện áp: 230-240V / 50Hz; Tổng công suất (W): 1270; Kiểu điều khiển: Cảm ứng / Núm xoay; KT (R×S×C mm): 495 x 370 x 290; Dung tích (lít): 25; Công nghệ: Inverter; Loại lò: Vi sóng + nướng; Kiểu khoang: Có đĩa quay; Công suất vi sóng (W): 800; Số mức công suất: 5', 1, 6, 1),
(35, 'LVS-KAF-002', 'Lò vi sóng Kaff KF-OMS44L', 21800000, 15790000, 8, '/img/sp/lvs-kaf-002/1.jpg', NULL, '44 lít', 36, 'Lò vi sóng Kaff KF-OMS44L là mẫu lò vi sóng âm tủ kết hợp nướng, mang đến giải pháp hai trong một cho những gian bếp muốn tối ưu số lượng thiết bị mà vẫn đảm bảo đầy đủ chức năng chế biến. Sản phẩm được lắp chìm vào hệ tủ bếp, giúp mặt bếp gọn gàng và tổng thể khu vực nấu trông đồng bộ hơn.\nVề thiết kế và lắp đặt, lò có kích thước sản phẩm 455C x 595R x 550S mm với kích thước âm tủ 450C x 560-568R x 595S mm, tương thích với các hộc tủ tiêu chuẩn nên dễ phối vào tủ bếp đóng sẵn. Cửa lò thiết kế kín toàn phần, có thông gió và dễ dàng vệ sinh, hạn chế tình trạng bám bẩn lâu ngày ở các khe kẽ.\nHệ điều khiển cảm ứng kèm hẹn giờ điện tử cho thao tác nhanh gọn, đồng thời giữ bề mặt phẳng mịn dễ lau chùi. Về hiệu năng, máy có tổng công suất 3350W, trong đó mức công suất vi sóng đạt 900W phục vụ hâm nóng và rã đông, còn mức công suất nướng 1750W đảm nhiệm các món cần độ vàng giòn.', 'Thương hiệu: Kaff (Đức); Model: KF-OMS44L; Sản xuất tại: Malaysia; Kiểu lắp: Âm tủ; Điện áp: 220-240V / 50Hz; Tổng công suất (W): 3350; Kiểu điều khiển: Cảm ứng; KT (R×S×C mm): 595 x 548 x 454; Công suất nướng (W): 1750; Dung tích (lít): 44; Loại lò: Vi sóng + nướng + đối lưu; Công suất vi sóng (W): 900; Số mức công suất: 5; KT khoét tủ (R×S×C mm): 560 x 568 x 450; An toàn: Có', 1, 6, 2),
(36, 'LVS-BOS-003', 'Lò vi sóng Bosch BEL7321B1', 35900000, 30120000, 0, '/img/sp/lvs-bos-003/1.jpg', '/img/sp/lvs-bos-003/2.jpg|/img/sp/lvs-bos-003/3.jpg', '21 lít', 36, 'Lò vi sóng kết hợp nướng âm tủ Bosch BEL7321B1 thuộc dòng Serie 8, là lựa chọn đáng cân nhắc cho những căn bếp hiện đại đề cao sự tinh gọn và công nghệ. Sản phẩm mang thương hiệu Bosch của Đức, được sản xuất tại Anh, kết hợp giữa khả năng hâm nóng, rã đông nhanh của vi sóng và chức năng nướng grill trong cùng một thiết bị, giúp rút ngắn đáng kể thời gian chuẩn bị bữa ăn hằng ngày.\nVề thiết kế, BEL7321B1 sở hữu mặt kính đen sang trọng, lắp âm tủ để bề mặt lò phẳng đều với hệ tủ bếp, tạo cảm giác liền mạch và đồng bộ với các thiết bị âm tủ khác. Khoang lò dung tích 21 lít với bề mặt bên trong bằng thép không gỉ nhẵn bóng, hạn chế góc cạnh nên rất dễ lau chùi sau khi sử dụng.\nĐáy khoang bằng kính cùng lớp hoàn thiện cao cấp giúp lò giữ được vẻ đẹp bền lâu. Kích thước sản phẩm 382 x 594 x 318 mm, hộc tủ lắp đặt cần 362–382 x 560–568 x 300 mm, phù hợp với đa số tủ bếp tiêu chuẩn.', 'Thương hiệu: Bosch (Đức); Model: BEL7321B1; Sản xuất tại: Anh; Kiểu lắp: Âm tủ; Điện áp: 220-240V / 50-60Hz; Tổng công suất (W): 2050; Kiểu điều khiển: Cảm ứng; KT (R×S×C mm): 594 x 318 x 382; Dung tích (lít): 21; Công nghệ: Inverter; Loại lò: Vi sóng + nướng; Kiểu khoang: Không đĩa quay (đáy phẳng); Công suất vi sóng (W): 900; Số mức công suất: 5', 0, 6, 1),
(37, 'BHN-KAF-004', 'Bếp đôi từ hồng ngoại Kaff KF-IC3801', 16800000, 11060000, 6, '/img/sp/bhn-kaf-004/1.jpg', '/img/sp/bhn-kaf-004/2.jpg|/img/sp/bhn-kaf-004/3.jpg', '5900W', 36, 'Bếp điện từ Kaff KF-IC3801 là mẫu bếp ba vùng nấu lắp âm kết hợp hai vùng từ và một vùng hồng ngoại, nhập khẩu nguyên chiếc từ Malaysia. Đây là lựa chọn dành cho gia đình cần nấu nhanh, nấu nhiều món cùng lúc nhưng vẫn muốn giữ sự linh hoạt để dùng được cả những bộ nồi không nhiễm từ có sẵn trong nhà.\nMặt bếp sử dụng kính Crystal siêu bền, chịu lực và chịu sốc nhiệt tốt, chống trầy xước, tản nhiệt nhanh và cách điện an toàn với các linh kiện điện tử bên trong thân bếp. Bề mặt liền khối, sáng bóng, chỉ cần lau bằng khăn ẩm là sạch, giúp việc giữ gìn mặt bếp trở nên nhẹ nhàng.\nKích thước mặt kính 750x450 mm và kích thước khoét đá 730x400 mm, đường kính vùng nấu giữa khoảng 16 cm còn hai vùng nấu trái và phải khoảng 22 cm, bố trí rộng rãi để đặt nhiều nồi cùng lúc. Ba vùng nấu có công suất lần lượt 1800W, 1500W và 2200W.', 'Thương hiệu: Kaff (Đức); Model: KF-IC3801; Sản xuất tại: Malaysia; Kiểu lắp: Âm tủ; Chất liệu: Kính; Điện áp: 220-240V; Tổng công suất (W): 5900; Kiểu điều khiển: Cảm ứng; Số vùng nấu: 3; KT mặt kính (R×S mm): 750 x 450; KT khoét đá (R×S mm): 730 x 400; Công suất từng vùng (W): 2200 + 1500 + 2200; Booster: Có; CS Booster tối đa (W): 3500; Mặt kính: Schott Ceran (Đức); Công nghệ bo mạch: Inverter; Số vùng từ: 2; Số vùng hồng ngoại: 1; Loại mâm nhiệt: Hi-Light (Radiant); Thương hiệu mâm nhiệt: E.G.O (Đức)', 1, 2, 2),
(38, 'HM-KOC-002', 'Máy hút mùi Kocher K-2080E 70cm', 17100000, 11890000, 12, '/img/sp/hm-koc-002/1.jpg', '/img/sp/hm-koc-002/2.jpg', '1800 m3/h', 36, 'Máy hút mùi Kocher K-2080E 70cm mang đến giải pháp làm sạch không khí bếp hiệu quả, kết hợp giữa công nghệ cao và thiết kế, giúp không gian bếp luôn trong lành, không mùi khói và đồng thời nâng tầm thẩm mỹ cho căn bếp hiện đại. Với kích thước 700 mm (rộng) × 430 mm (sâu) × 1281 mm (cao), máy được lắp đặt gắn tường, thiết kế vát kính tự động mở, mặt kính cường lực sang trọng và khung inox cao cấp, tạo nên một thiết kế, bền bỉ và chịu nhiệt tốt.\nHệ thống lọc mỡ bằng lưới inox và tùy chọn bộ lọc than hoạt tính giúp duy trì hiệu suất lâu dài mà không ảnh hưởng đến thẩm mỹ. Công nghệ Ultra Swing A++ của Kocher, động cơ 220 W, cung cấp công suất hút 1400 m³/h, đáp ứng tiêu chuẩn châu Âu A++.\nMáy có ba cấp độ hút, màn hình LCD cảm ứng và chức năng hẹn giờ linh hoạt, cho phép người dùng điều chỉnh nhanh chóng theo nhu cầu nấu nướng.', 'Thương hiệu: Kocher (Đức); Model: K-2080E 70cm; Sản xuất tại: Malaysia; Kiểu lắp: Áp tường; Chất liệu: Inox / Kính cường lực; Điện áp: 220V; Tổng công suất (W): 220; Kiểu điều khiển: Cảm ứng; KT máy (R×S×C mm): 700 x 430; Lưu lượng hút (m³/h): 1800; Độ ồn (dB): 46; Số cấp tốc độ: 3; Số motor: 1; Công suất motor (W): 220; Loại lọc: Lọc mỡ / Lọc than hoạt tính (khử mùi); Đèn chiếu sáng: LED; Bề rộng (mm): 700; Chất liệu lưới lọc: Inox', 1, 3, 3),
(39, 'MRC-KAF-002', 'Máy rửa chén Kaff KF-BHMI775YS', 27800000, 21970000, 4, '/img/sp/mrc-kaf-002/1.jpg', NULL, '17 bộ', 36, 'Máy rửa chén Kaff KF-BHMI775YS là phiên bản vỏ inox màu bạc của dòng BHMI775Y, giữ nguyên toàn bộ cấu hình cao cấp và chỉ khác biệt ở tông màu bên ngoài. Đây là lựa chọn dành cho những căn bếp sử dụng nhiều thiết bị inox sáng màu, muốn tổng thể đồng bộ và cảm giác rộng thoáng hơn so với bản màu đen.\nMáy có sức chứa 17 bộ đồ ăn châu Âu với 3 dàn rửa, kích thước 775 x 598R x 600S mm nên có thể đặt độc lập hoặc lắp âm dưới mặt bàn bếp. Vỏ ngoài inox cao cấp cho độ bền cao, chống bám bẩn, chống ăn mòn và rất dễ lau chùi trong môi trường bếp nhiều hơi nước.\nBa dàn rửa được thiết kế để tối ưu không gian: hai giàn dưới dành cho bát đĩa, nồi chảo và ly cốc, khay trên cùng dành riêng cho dao, dĩa, thìa. Bảng điều khiển cảm ứng cùng màn hình LED cho thao tác nhẹ nhàng và hiển thị trạng thái rõ ràng.', 'Thương hiệu: Kaff (Đức); Model: KF-BHMI775YS; Sản xuất tại: Thái Lan; Kiểu lắp: Độc lập; Điện áp: 220-240V; Độ ồn (dB): 48; Số bộ (place settings): 17; Số chương trình: 8; Công nghệ sấy: Sấy khí nóng (PTC); Điện/chu trình (kWh): 0,92; Nước/chu trình (lít): 6; KT phủ bì (R×S mm): 600 x 775; KT khoét (R×C mm): 598 x 600; KT (R×S×C mm): 600 x 598 x 775; An toàn: khóa trẻ em', 1, 4, 2),
(40, 'LN-KOC-002', 'Lò nướng Kocher KOEU-71S13F', 19700000, 11770000, 9, '/img/sp/ln-koc-002/1.jpg', NULL, '71 lít', 36, 'Lò nướng âm tủ Kocher KOEU-71S13F là mẫu lò dung tích lớn với 13 chương trình nướng tự động, hướng tới những gia đình yêu bếp và muốn có nhiều lựa chọn chế biến hơn. Sản phẩm mang thương hiệu Kocher xuất xứ Đức, sản xuất tại Đức, bảo hành chính hãng 36 tháng.\nVề thiết kế, lò mang thiết kế theo phong cách châu Âu với vỏ ngoài bằng thép không gỉ siêu bền, sáng bóng và dễ vệ sinh. Kiểu lắp âm tủ giúp tối ưu diện tích bếp và tạo sự liền mạch cho tổng thể.\nCửa lò dày dặn với hệ thống nhiều lớp kính cách nhiệt, cụ thể là mặt kính 3 lớp chịu lực chịu nhiệt, vừa giữ nhiệt hiệu quả bên trong vừa tránh nguy cơ bỏng khi chạm vào cánh cửa. Thiết kế mở phía trước giúp thao tác đưa khay vào và lấy ra thuận tiện.\nKích thước sản phẩm 595 cao x 575 rộng x 595 sâu mm. Khoang lò dung tích 71 lít cho phép nướng nhiều thực phẩm trong cùng một lần mà vẫn đảm bảo chín đều mọi mặt.', 'Thương hiệu: Kocher (Đức); Model: KOEU-71S13F; Sản xuất tại: Đức; Kiểu lắp: Âm tủ; Chất liệu: Inox; Điện áp: 220-240V / 50Hz; Tổng công suất (W): 2300; Kiểu điều khiển: Cảm ứng; KT (R×S×C mm): 595 x 575 x 595; Số lớp kính cửa: 3; Dung tích (lít): 71; Số chức năng nướng: 13; Công nghệ: Khí nóng 3D (3D hot air); Chức năng: 13 chương trình nấu, nướng tự động; An toàn: Khóa an toàn trẻ em, kính 3 lớp chịu nhiệt', 1, 5, 3);
